def rank_with_average_ties(nums):
    ordered = sorted(nums)
    n = len(ordered)
    rank_map = {}
    i = 0
    while i < n:
        j = i
        while j < n and ordered[j] == ordered[i]:
            j += 1
        avg_rank = (i + 1 + j) / 2
        for k in range(i, j):
            rank_map.setdefault(ordered[k], avg_rank)
        i = j
    return [rank_map[x] for x in nums]

def group_indices_in_range(seq, low, high):
    out = {}
    for idx in range(len(seq)):
        val = seq[idx]
        if low <= val <= high:
