def longest_increasing_run_length(lst):
    if not lst:
        return 0
    longest = 1
    run = 1
    for i in range(1, len(lst)):
        if lst[i] > lst[i - 1]:
            run += 1
            longest = max(longest, run)
        else:
            run = 1
    return longest

