def capitalize_first_word_each_line(text):
    lines = text.split('\n')
    result_lines = []
    for line in lines:
        if line == '':
            result_lines.append(line)
            continue
        lower_line = line.lower()
        idx = None
        for i, ch in enumerate(lower_line):
            if ch.isalpha():
                idx = i
                break
        if idx is None:
            result_lines.append(lower_line)
        else:
            result_lines.append(lower_line[:idx] + lower_line[idx].upper() + lower_line[idx + 1:])
    return '\n'.join(result_lines)

